"""SCOREBOARD.md, rendered from results/scoreboard.json and never typed by hand.

``craton check`` re-renders the board and fails if the Markdown differs from the JSON, so a
number can only reach the scoreboard through a benchmark run and the ratchet.
"""

from __future__ import annotations

from pathlib import Path

from craton.bench.catalog import BY_ID, CATALOG
from craton.bench.results import Scoreboard, ScoreEntry
from craton.paths import scoreboard_json, scoreboard_md

HEADER = (
    "<!-- Generated by `craton scoreboard` from results/scoreboard.json. Do not edit by hand:\n"
    "     `craton check` fails if this file and the JSON disagree. -->\n"
)

ARROW = {"lower": "↓", "higher": "↑"}


def _fmt(entry: ScoreEntry) -> str:
    return f"{entry.mean:.4g} ± {entry.std:.2g} {ARROW[entry.direction]}"


def render(board: Scoreboard) -> str:
    lines: list[str] = [HEADER, "# Scoreboard", ""]
    lines += [
        "Every number here comes from a script and is a mean ± std over 3 seeds. "
        "The ratchet only lets a number in if no other task gets worse beyond noise, "
        "so this table can only improve.",
        "",
        "## Headline",
        "",
        "| | Task | Now | Arrives |",
        "|---|---|---|---|",
    ]
    for task in (t for t in CATALOG if t.headline):
        entry = board.entries.get(task.task_id)
        now = _fmt(entry) if entry else "not measured yet"
        lines.append(
            f"| **{task.name}** | {task.task_id} · {task.measures} | {now} | {task.phase} |"
        )

    lines += [
        "",
        "## Every task",
        "",
        "| ID | Task | Score | Model | Run | Phase |",
        "|---|---|---|---|---|---|",
    ]
    known = {t.task_id for t in CATALOG}
    for task_id in sorted(known | set(board.entries)):
        planned = BY_ID.get(task_id)
        entry = board.entries.get(task_id)
        name = planned.name if planned else task_id
        phase = planned.phase if planned else "—"
        if entry:
            score, run = _fmt(entry), f"`{entry.run_id}`"
            lines.append(f"| {task_id} | {name} | {score} | {entry.model} | {run} | {phase} |")
        else:
            lines.append(f"| {task_id} | {name} | · | · | · | {phase} |")

    lines += ["", "## History", ""]
    if board.history:
        lines += ["| Accepted (UTC) | Run | Model | Ratchet |", "|---|---|---|---|"]
        for h in reversed(board.history):
            when = h.accepted.strftime("%Y-%m-%d %H:%M")
            lines.append(f"| {when} | `{h.run_id}` | {h.model} | {h.summary} |")
    else:
        lines.append(
            "No runs yet. The first real numbers are the simple baselines in P3, scored before "
            "any model exists, so the first model has something honest to beat."
        )
    lines.append("")
    return "\n".join(lines)


def write(root: Path) -> Path:
    board = Scoreboard.load(scoreboard_json(root))
    out = scoreboard_md(root)
    out.write_text(render(board), encoding="utf-8", newline="\n")
    return out


def integrity_problem(root: Path) -> str | None:
    """None if SCOREBOARD.md is exactly what the JSON renders to."""
    md = scoreboard_md(root)
    if not md.exists():
        return "SCOREBOARD.md is missing. Run `craton scoreboard`."
    expected = render(Scoreboard.load(scoreboard_json(root)))
    actual = md.read_text(encoding="utf-8").replace("\r\n", "\n")
    if actual != expected:
        return (
            "SCOREBOARD.md doesn't match results/scoreboard.json (edited by hand?). "
            "Run `craton scoreboard` to regenerate it."
        )
    return None
